def incorporar_saldos(apps, schema_editor):
    alias = schema_editor.connection.alias
    if 'stock_bodega' not in schema_editor.connection.introspection.table_names():
        return
    if schema_editor.connection.vendor == 'postgresql':
        with schema_editor.connection.cursor() as cursor:
            cursor.execute("SET LOCAL lock_timeout = '10s'")
            cursor.execute('LOCK TABLE stock_bodega IN SHARE ROW EXCLUSIVE MODE')
    Stock = apps.get_model('productos', 'StockBodega')
    Lote = apps.get_model('productos', 'Lote')
    Existencia = apps.get_model('productos', 'ExistenciaLote')
    for stock in Stock.objects.using(alias).filter(cantidad_total__gt=0).order_by('pk').iterator(chunk_size=500):
        lote, _ = Lote.objects.using(alias).get_or_create(
            codigo=f'INI-{stock.pk}',
            defaults={'producto_id': stock.producto_id, 'cantidad_inicial': stock.cantidad_total,
                      'referencia': 'Saldo anterior sin desglose de recepción',
                      'fecha_recepcion': stock.fecha_creacion, 'es_saldo_inicial': True, 'costo_unitario': None},
        )
        Existencia.objects.using(alias).get_or_create(
            lote_id=lote.pk, bodega_id=stock.bodega_id, defaults={'cantidad': stock.cantidad_total})


